import type { MarkdownFile, MoveFile, Card } from './data_types'
import { isSafeAssetFileName, isSupportedAssetFileName, resolveCardAssetPath } from './asset_paths'
import { markdownParsingService } from '../services/data/markdown_parsing_service'
import {
    activityFilePath,
    cardActivityFileName,
    conversationActivityReference,
    parseConversationActivityReference,
} from '../../../shared/activity_paths.mjs'
import { normalizePath } from '../../../shared/path_utils.mjs'

const RELEASE_NAME_PATTERN = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/u
const MARKDOWN_EXTENSION = '.md'
const MARKDOWN_IMAGE_LINK_PATTERN = /!\[[^\]]*\]\(([^)\s]+)(?:\s+["'][^)]*["'])?\)/gu

function isMarkdownFile(path: string) {
    return path.toLowerCase().endsWith(MARKDOWN_EXTENSION)
}

function isExternalAssetReference(reference: string) {
    return /^[a-z][a-z0-9+.-]*:/iu.test(reference) || reference.startsWith('#')
}

function cleanAssetReference(reference: string) {
    return reference.replace(/^<|>$/gu, '').trim()
}

function referencedCardAssets(file: MarkdownFile) {
    const assets: string[] = []

    for (const match of file.content.matchAll(MARKDOWN_IMAGE_LINK_PATTERN)) {
        const reference = cleanAssetReference(match[1])
        if (reference.length === 0 || isExternalAssetReference(reference)) continue
        if (!isSafeAssetFileName(reference) || !isSupportedAssetFileName(reference)) continue

        assets.push(resolveCardAssetPath(file.path, reference))
    }

    return assets
}

function targetPathForSource(targetFolder: string, sourcePath: string) {
    const fileName = sourcePath.split('/').at(-1)
    if (!fileName) throw new Error(`Cannot archive file without a file name: ${sourcePath}`)

    return `${targetFolder}/${fileName}`
}

function createMove(file: MarkdownFile, fromPath: string, toPath: string, encoding = file.encoding): MoveFile {
    const move = {
        content: file.content,
        fromPath,
        sha: file.sha,
        toPath,
    }
    if (encoding) return { ...move, encoding }

    return move
}

function releaseActivitySource(card: Card, projectFolder: string) {
    const cardInternalId = card.header.internalId
    if (!cardInternalId) throw new Error(`Cannot release a card without an internal ID: ${card.path}`)

    const sourcePath = activityFilePath(projectFolder, { cardInternalId, kind: 'card' })
    const conversationIds = card.header.agentLogReferences.map((reference) => {
        const parsed = parseConversationActivityReference(reference)
        if (normalizePath(parsed.activityPath) !== normalizePath(sourcePath)) {
            throw new Error(`Unexpected activity path for released card ${card.path}: ${parsed.activityPath}`)
        }

        return parsed.conversationId
    })

    return { cardInternalId, conversationIds, sourcePath }
}

export function findReleaseActivityPaths(
    releaseCards: Card[],
    projectFolder: string,
    repositoryFiles: string[],
) {
    const repositoryPaths = new Set(repositoryFiles.map(normalizePath))
    const activityPaths = new Set<string>()

    for (const card of releaseCards) {
        const { conversationIds, sourcePath } = releaseActivitySource(card, projectFolder)
        const normalizedSourcePath = normalizePath(sourcePath)
        const exists = repositoryPaths.has(normalizedSourcePath)
        if (conversationIds.length > 0 && !exists) throw new Error(`Missing referenced activity log: ${sourcePath}`)
        if (exists) activityPaths.add(sourcePath)
    }

    return [...activityPaths]
}

export function validateReleaseName(releaseName: string) {
    const trimmedName = releaseName.trim()

    if (trimmedName.length === 0) throw new Error('Release name is required')
    if (!RELEASE_NAME_PATTERN.test(trimmedName)) {
        throw new Error('Release name may contain only letters, numbers, dots, underscores and hyphens')
    }
    if (trimmedName === '.' || trimmedName === '..') throw new Error('Release name must be a safe folder name')

    return trimmedName
}

export function findArchiveAssetPaths(files: MarkdownFile[], archivedCards: Card[]) {
    const archivedSourcePaths = new Set(archivedCards.map((card) => normalizePath(card.path)))
    const nonArchivedAssetPaths = new Set(
        files
            .filter((file) => isMarkdownFile(file.path) && !archivedSourcePaths.has(normalizePath(file.path)))
            .flatMap(referencedCardAssets)
            .map(normalizePath),
    )
    const assetPaths: string[] = []
    const plannedAssetPaths = new Set<string>()

    for (const card of archivedCards) {
        const file = files.find((candidate) => normalizePath(candidate.path) === normalizePath(card.path))
        if (!file) continue

        for (const assetPath of referencedCardAssets(file).map(normalizePath)) {
            if (nonArchivedAssetPaths.has(assetPath) || plannedAssetPaths.has(assetPath)) continue

            plannedAssetPaths.add(assetPath)
            assetPaths.push(assetPath)
        }
    }

    return assetPaths
}

export function buildReleaseMoves(
    files: MarkdownFile[],
    activeCards: Card[],
    projectFolder: string,
    releasesFolder: string,
    safeReleaseName: string,
    repositoryFiles: string[] = [],
    activityFiles: MarkdownFile[] = [],
): MoveFile[] {
    const normalizedProjectFolder = normalizePath(projectFolder).replace(/\/+$/u, '')
    const normalizedReleasesFolder = normalizePath(releasesFolder).replace(/\/+$/u, '')
    const projectPrefix = normalizedProjectFolder.length > 0 ? `${normalizedProjectFolder}/` : ''
    if (
        normalizedReleasesFolder !== normalizedProjectFolder
        && !normalizedReleasesFolder.startsWith(projectPrefix)
    ) {
        throw new Error(`Releases folder must stay inside the project folder: ${releasesFolder}`)
    }

    const targetFolder = `${normalizedReleasesFolder}/${safeReleaseName}`
    const normalizedTargetFolder = `${targetFolder}/`
    const existingPaths = new Set([
        ...files.map((file) => normalizePath(file.path)),
        ...repositoryFiles.map(normalizePath),
    ])
    const hasExistingReleaseFolder = [...existingPaths].some((path) => path.startsWith(normalizedTargetFolder))

    if (hasExistingReleaseFolder) throw new Error(`Release already exists: ${safeReleaseName}`)

    const moves = buildCardArchiveMoves(files, activeCards, targetFolder, repositoryFiles)
    const repositoryPaths = new Set(repositoryFiles.map(normalizePath))
    const activityFilesByPath = new Map(activityFiles.map((file) => [normalizePath(file.path), file]))
    const targetPaths = new Set(moves.map((move) => normalizePath(move.toPath)))
    const cardActivityMoves = new Map<string, MoveFile>()
    const rewrittenCardContentByPath = new Map<string, string>()

    for (const card of activeCards) {
        const { cardInternalId, conversationIds, sourcePath } = releaseActivitySource(card, projectFolder)
        const normalizedSourcePath = normalizePath(sourcePath)
        const activityExists = repositoryPaths.has(normalizedSourcePath)
        if (conversationIds.length > 0 && !activityExists) throw new Error(`Missing referenced activity log: ${sourcePath}`)
        if (!activityExists) continue

        const activityFile = activityFilesByPath.get(normalizedSourcePath)
        if (!activityFile) throw new Error(`Cannot release unloaded activity log: ${sourcePath}`)
        const activityTargetPath = `${targetFolder}/${cardActivityFileName(cardInternalId)}`
        const normalizedActivityTargetPath = normalizePath(activityTargetPath)
        if (existingPaths.has(normalizedActivityTargetPath) || targetPaths.has(normalizedActivityTargetPath)) {
            throw new Error(`Archive target already exists: ${activityTargetPath}`)
        }

        targetPaths.add(normalizedActivityTargetPath)
        cardActivityMoves.set(normalizePath(card.path), createMove(activityFile, sourcePath, activityTargetPath))

        if (conversationIds.length === 0) continue
        const references = conversationIds.map((conversationId) => (
            conversationActivityReference(activityTargetPath, conversationId)
        ))
        const cardMove = moves.find((move) => normalizePath(move.fromPath) === normalizePath(card.path))
        if (!cardMove) throw new Error(`Cannot find release move for card: ${card.path}`)
        rewrittenCardContentByPath.set(
            normalizePath(card.path),
            markdownParsingService.setAgentLogReferences(cardMove.content, references),
        )
    }

    return moves.flatMap((move) => {
        const activityMove = cardActivityMoves.get(normalizePath(move.fromPath))
        const rewrittenContent = rewrittenCardContentByPath.get(normalizePath(move.fromPath))
        const preparedMove = rewrittenContent === undefined ? move : { ...move, content: rewrittenContent }

        return activityMove ? [preparedMove, activityMove] : [preparedMove]
    })
}

export function buildCardArchiveMoves(
    files: MarkdownFile[],
    archivedCards: Card[],
    targetFolder: string,
    repositoryFiles: string[] = [],
): MoveFile[] {
    const existingPaths = new Set([
        ...files.map((file) => normalizePath(file.path)),
        ...repositoryFiles.map(normalizePath),
    ])
    const filesByPath = new Map(files.map((file) => [normalizePath(file.path), file]))
    const archiveAssetPaths = new Set(findArchiveAssetPaths(files, archivedCards))
    const moveTargetPaths = new Set<string>()
    const moves: MoveFile[] = []

    for (const card of archivedCards) {
        const sourcePath = normalizePath(card.path)
        const toPath = targetPathForSource(targetFolder, sourcePath)

        if (existingPaths.has(toPath) || moveTargetPaths.has(toPath)) throw new Error(`Archive target already exists: ${toPath}`)
        const file = filesByPath.get(sourcePath)
        if (!file) throw new Error(`Cannot archive unloaded card file: ${card.path}`)

        moveTargetPaths.add(toPath)
        moves.push(createMove(file, card.path, toPath))

        for (const assetPath of referencedCardAssets(file).map(normalizePath)) {
            if (!archiveAssetPaths.has(assetPath)) continue

            const assetTargetPath = targetPathForSource(targetFolder, assetPath)
            if (existingPaths.has(assetTargetPath) || moveTargetPaths.has(assetTargetPath)) {
                throw new Error(`Archive target already exists: ${assetTargetPath}`)
            }

            const assetFile = filesByPath.get(assetPath)
            if (!assetFile) throw new Error(`Cannot archive unloaded card asset: ${assetPath}`)

            moveTargetPaths.add(assetTargetPath)
            moves.push(createMove(assetFile, assetPath, assetTargetPath, 'base64'))
            archiveAssetPaths.delete(assetPath)
        }
    }

    return moves
}

import { computeMove } from '../../data/card_ordering'
import type { MarkdownFile } from '../../data/data_types'
import { buildCardArchiveMoves, findArchiveAssetPaths } from '../../data/release_archiving'
import type { CardOperationContext } from './card_operation_context'
import { markdownParsingService } from './markdown_parsing_service'

/** Moves a card and its assets into the archived folder in one commit. */
export class CardArchiveOperations {
    private readonly context: CardOperationContext
    private readonly triggerStateActions: (cardPath: string, state: string) => void

    constructor(context: CardOperationContext, triggerStateActions: (cardPath: string, state: string) => void) {
        this.context = context
        this.triggerStateActions = triggerStateActions
    }

    async archiveCard(cardPath: string, targetIndex: number) {
        const { dependencies } = this.context
        const { config, project, storage } = this.context.requireProject('archive a card')

        await this.context.flushPendingCommits()

        const snapshot = dependencies.snapshot()
        const activeCards = snapshot?.activeCards ?? []
        const archivedCard = activeCards.find((card) => card.path === cardPath)
        if (!archivedCard) throw new Error(`Cannot archive an active card that is not loaded: ${cardPath}`)

        const updates = computeMove(activeCards, cardPath, 'archived', targetIndex)
        const updatedCards = this.context.applyOrderingUpdates(updates)
        const updatedFiles = updatedCards.map((card) => markdownParsingService.serializeCard(card))
        const files = this.context.mergeUpdatedFiles(updatedFiles)
        const assetFiles = await this.loadArchiveAssets(findArchiveAssetPaths(files, [archivedCard]))
        const moves = buildCardArchiveMoves(
            [...files, ...assetFiles],
            [archivedCard],
            config.archivedFolder,
            snapshot?.repositoryFiles ?? [],
        )
        const orderingFiles = updatedFiles.filter((file) => file.path !== cardPath)

        await this.context.commitTrackingPaths({
            branch: project.branch,
            files: orderingFiles,
            message: `Archive ${cardPath}`,
            moves,
        })

        this.triggerStateActions(cardPath, 'archived')
        if (config.pushMode === 'auto') await storage.push(project)
        if (config.pushMode === 'manual') dependencies.dispatchPersistenceChanged()
        dependencies.applyMoves(moves, config.workingFolder)
        dependencies.dispatchChanged()

        const cardMove = moves.find((move) => move.fromPath === cardPath)
        if (!cardMove) throw new Error(`Missing archived card move: ${cardPath}`)

        dependencies.cardPathChanged(cardPath, cardMove.toPath)

        return updates
    }

    private async loadArchiveAssets(assetPaths: string[]): Promise<MarkdownFile[]> {
        if (assetPaths.length === 0) return []

        const { project, storage } = this.context.requireProject('load archived card assets')
        if (!storage.loadProjectAsset) throw new Error('Project asset loading is not available')

        const assets: MarkdownFile[] = []
        for (const assetPath of assetPaths) {
            const asset = await storage.loadProjectAsset(project, assetPath)
            assets.push({ content: asset.content, encoding: asset.encoding, path: asset.path })
        }

        return assets
    }
}

import {
    buildReleaseMoves,
    findArchiveAssetPaths,
    findReleaseActivityPaths,
    validateReleaseName,
} from '../data/release_archiving'
import { statusOf } from '../data/card_ordering'
import { projectAccessService } from './project/project_access_service'
import type { MarkdownFile, MoveFile, ProjectAsset, ProjectReference, ProjectSnapshot, ReleaseBranchCandidate } from '../data/data_types'
import { type RequiredDataServiceDependencies } from './data/data_service_context'
import { markdownParsingService } from './data/markdown_parsing_service'
import { telemetryService } from './telemetry/telemetry_service'

export interface ReleaseOperationsDeps {
    applyMoves(moves: MoveFile[], workingFolder: string): void
    dispatchChanged(): void
    files(): MarkdownFile[]
    project(): ProjectReference | null
    requireDependencies(): RequiredDataServiceDependencies
    snapshot(): ProjectSnapshot | null
}

function requireNoAssignedWorktrees(activeCards: ProjectSnapshot['activeCards']) {
    const assignedCardIds = activeCards
        .filter((card) => card.header.worktree !== null && card.header.worktree !== undefined)
        .map((card) => card.header.id)
    if (assignedCardIds.length > 0) {
        throw new Error(`Cannot complete release. Unassign worktrees from cards: ${assignedCardIds.join(', ')}.`)
    }
}

export class ReleaseOperations {
    private readonly dependencies: ReleaseOperationsDeps
    private readonly flushPendingCommitBatch: () => Promise<void>

    constructor(
        dependencies: ReleaseOperationsDeps,
        flushPendingCommitBatch: () => Promise<void>,
    ) {
        this.dependencies = dependencies
        this.flushPendingCommitBatch = flushPendingCommitBatch
    }

    async getReleaseBranchCandidates(): Promise<ReleaseBranchCandidate[]> {
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release branches before a project is open')

        const activeCards = this.dependencies.snapshot()?.activeCards ?? []
        requireNoAssignedWorktrees(activeCards)
        if (!storage.deleteLocalBranch) return []

        const finalState = config.states.at(-1)
        if (!finalState) throw new Error('Cannot complete a release without configured states')
        const localBranches = new Set((await storage.listBranches(currentProject)).map(({ name }) => name))

        return activeCards
            .filter((card) => statusOf(card) === finalState.state)
            .filter((card) => !!card.header.branch && localBranches.has(card.header.branch))
            .filter((card) => card.header.branch !== currentProject.branch && !card.header.branch?.startsWith('md2/parking/'))
            .map((card) => {
                const branchName = card.header.branch
                if (!branchName) throw new Error(`Release branch identity is missing: ${card.header.id}`)

                return { branchName, cardId: card.header.id, cardPath: card.path }
            })
    }

    async completeRelease(releaseName: string, selectedBranchNames: string[]) {
        projectAccessService.requireWritable()
        const { config, storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot complete a release before a project is open')

        const safeReleaseName = validateReleaseName(releaseName)
        await this.flushPendingCommitBatch()

        const finalState = config.states.at(-1)
        if (!finalState) throw new Error('Cannot complete a release without configured states')

        const activeCards = this.dependencies.snapshot()?.activeCards ?? []
        requireNoAssignedWorktrees(activeCards)
        const releaseCards = activeCards.filter((card) => statusOf(card) === finalState.state)
        if (releaseCards.length === 0) throw new Error(`Cannot complete a release without cards in the final column: ${finalState.state}`)

        const candidates = await this.getReleaseBranchCandidates()
        const candidateByBranch = new Map(candidates.map((candidate) => [candidate.branchName, candidate]))
        const uniqueSelectedBranchNames = [...new Set(selectedBranchNames)]
        const invalidBranch = uniqueSelectedBranchNames.find((branchName) => !candidateByBranch.has(branchName))
        if (invalidBranch) throw new Error(`Branch is not available for this release: ${invalidBranch}`)
        if (uniqueSelectedBranchNames.length > 0 && !storage.deleteLocalBranch) {
            throw new Error('Local branch deletion is not available')
        }

        const repositoryFiles = this.dependencies.snapshot()?.repositoryFiles ?? []
        const files = this.dependencies.files()
        const assetPaths = findArchiveAssetPaths(files, releaseCards)
        const assetFiles = await this.loadReleaseAssets(assetPaths)
        const activityPaths = findReleaseActivityPaths(releaseCards, config.projectFolder, repositoryFiles)
        const activityFiles = await this.loadReleaseActivityFiles(activityPaths)
        const moves = buildReleaseMoves(
            [...files, ...assetFiles],
            releaseCards,
            config.projectFolder,
            config.releasesFolder,
            safeReleaseName,
            repositoryFiles,
            activityFiles,
        )
        await storage.moveFiles({
            branch: currentProject.branch,
            message: `Complete release ${safeReleaseName}`,
            moves,
        })

        if (config.pushMode === 'auto') await storage.push(currentProject)

        const deletedCandidates: ReleaseBranchCandidate[] = []
        const cleanupFailures: string[] = []
        for (const branchName of uniqueSelectedBranchNames) {
            try {
                if (!storage.deleteLocalBranch) throw new Error('Local branch deletion is not available')
                await storage.deleteLocalBranch(currentProject, branchName)
                const candidate = candidateByBranch.get(branchName)
                if (!candidate) throw new Error(`Release branch candidate disappeared: ${branchName}`)
                deletedCandidates.push(candidate)
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error)
                cleanupFailures.push(`${branchName}: ${message}`)
            }
        }

        let clearedFiles: MarkdownFile[] = []
        if (deletedCandidates.length > 0) {
            try {
                const preparedClearedFiles = deletedCandidates.map((candidate) => {
                    const move = moves.find(({ fromPath }) => fromPath === candidate.cardPath)
                    if (!move) throw new Error(`Released card move is missing: ${candidate.cardId}`)

                    return { content: markdownParsingService.setBranch(move.content, null), path: move.toPath }
                })
                const committedFiles = await storage.commit({
                    branch: currentProject.branch,
                    files: preparedClearedFiles,
                    message: 'Clear deleted release branches',
                })
                clearedFiles = committedFiles.length > 0 ? committedFiles : preparedClearedFiles
                if (config.pushMode === 'auto') await storage.push(currentProject)
            } catch (error) {
                const message = error instanceof Error ? error.message : String(error)
                cleanupFailures.push(`branch metadata: ${message}`)
            }
        }

        const clearedFilesByPath = new Map(clearedFiles.map((file) => [file.path, file]))
        const appliedMoves = moves.map((move) => {
            const clearedFile = clearedFilesByPath.get(move.toPath)
            return clearedFile ? { ...move, content: clearedFile.content, sha: clearedFile.sha } : move
        })
        this.dependencies.applyMoves(appliedMoves, config.workingFolder)
        this.dependencies.dispatchChanged()
        telemetryService.trackEvent('complete_release')

        if (cleanupFailures.length > 0) {
            throw new Error(`Release completed, but branch cleanup failed: ${cleanupFailures.join('; ')}`)
        }

        return this.dependencies.snapshot()
    }

    private async loadReleaseAssets(assetPaths: string[]) {
        if (assetPaths.length === 0) return []

        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release assets before a project is open')
        if (!storage.loadProjectAsset) throw new Error('Project asset loading is not available')

        const assets: ProjectAsset[] = []
        for (const assetPath of assetPaths) {
            assets.push(await storage.loadProjectAsset(currentProject, assetPath))
        }

        return assets.map((asset): MarkdownFile => ({
            content: asset.content,
            encoding: asset.encoding,
            path: asset.path,
        }))
    }

    private async loadReleaseActivityFiles(activityPaths: string[]) {
        if (activityPaths.length === 0) return []

        const { storage } = this.dependencies.requireDependencies()
        const currentProject = this.dependencies.project()
        if (!currentProject) throw new Error('Cannot load release activity before a project is open')
        if (!storage.loadTextFile) throw new Error('Repository text file loading is not available')

        const activityFiles: MarkdownFile[] = []
        for (const activityPath of activityPaths) {
            activityFiles.push(await storage.loadTextFile(currentProject, activityPath))
        }

        return activityFiles
    }
}

