                        states={states}
                    />
                    {isMobile ? createButton : (
                        <Stack direction="row" spacing={1}>
                            <Button onClick={closeDialog} type="button" variant="outlined">
                                Cancel
                            </Button>
                            {createButton}
                        </Stack>
                    )}
                </DialogActions>
            </Box>
        </Dialog>
    )
